describe('useDebounceValue Hook', () => {
  it('updates debounced value only after delayMs', () => {
    vi.useFakeTimers();
    const { result, rerender } = renderHook(({ val }) => useDebounceValue(val, 300), {
      initialProps: { val: 'first' }
    });
    expect(result.current).toBe('first');
    rerender({ val: 'second' });
    expect(result.current).toBe('first');
    act(() => {
      vi.advanceTimersByTime(300);
    });
    expect(result.current).toBe('second');
    vi.useRealTimers();
  });
});

describe('useLocalStorageState Hook', () => {
  beforeEach(() => {
    window.localStorage.clear();
  });

  it('initializes from default value and writes to localStorage on update', () => {
    const { result } = renderHook(() => useLocalStorageState('test_key', 'initial'));
    expect(result.current[0]).toBe('initial');
    act(() => {
      result.current[1]('updated');
    });
    expect(result.current[0]).toBe('updated');
    expect(window.localStorage.getItem('test_key')).toBe(JSON.stringify('updated'));
  });
});

